SELECT count(*) FILTER (WHERE daewoong_amount_actual IS NOT NULL) AS 실판매액있음, sum(daewoong_amount_actual) AS 실판매액합, count(*) FILTER (WHERE hospital_model_id IS NOT NULL) AS 판매모델있음, count(*) FILTER (WHERE daewoong_tax_invoice IS NOT NULL) AS 세금계산서있음 FROM sales_deals;
